local OnlineRewardCellPath = 'Game.Entry.OnlineRewardCell'
------------ define ------------

--- from: Assets/BundleResources/Prefabs/OnlineReward/OnlineRewardPopup.prefab > name: OnlineRewardPopup
---@class OnlineRewardPreviewDialog
---@field Env                            OnlineRewardPreviewDialog
---@field controller                        Engine.UI.UILuaDialog
---@field ClickClose                        UnityEngine.RectTransform                @ 0
---@field UIFX_Extract                    UnityEngine.RectTransform                @ 1
---@field Content                        UnityEngine.RectTransform                @ 2
---@field TextDesc                        UnityEngine.RectTransform                @ 3
---@field OnlineRewardCell                UnityEngine.RectTransform                @ 4
---@field ChestList                        SuperScrollView.LoopListView2            @ 5
---@field BtnClose                        UnityEngine.RectTransform                @ 6
local OnlineRewardPreviewDialog = Class("OnlineRewardPreviewDialog")

function OnlineRewardPreviewDialog:__init()
    self.data = nil
    self.position = nil
end

function OnlineRewardPreviewDialog:__delete()
    self.data = nil
    self.position = nil
    self.controller = nil
end

function OnlineRewardPreviewDialog:Awake()
    SetButtonAction(self.BtnClose, function()
        CfUtils.DialogBack()
    end)
    SetButtonAction(self.ClickClose, function()
        CfUtils.DialogBack()
    end)
end

---OnCellNodeAction
---点击奖励领取的逻辑
---@param data table
function OnlineRewardPreviewDialog:OnCellNodeAction(data)
    local taskId = checkNumber(data.id)
    local taskType = checkNumber(data.type)
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    ---@type PlayerDojo
    local playerDojo = playerComponent.playerDojo
    local t = {}
    if taskType == 2 then
        ---1类型的数据
        table.insert(t, taskId)
    else
        for _, position in pairs(self.position) do
            local reward = self.data[position]
            local status = checkNumber(reward.status)
            local time = checkNumber(reward.targetNum) - checkNumber(reward.progress)
            time = math.max(0, time)
            if status == 1 or (time <= 0 and status ~= 2) then
                table.insert(t, reward.id)
            end
        end
    end
    GameUtils.Request(Interfaces.OverseaOnlineDraw, { taskIds = table.serialize(t) }, function(request, response)
        local code = checkNumber(response.errCode)
        if code == 0 then
            local responseData = checkTable(response.data)
            for i, v in pairs(playerDojo.onlineTaskInfo.taskList) do
                if table.find(t, function(tId)
                    return checkNumber(tId) == checkNumber(v.id)
                end) then
                --if checkNumber(v.id) == taskId then
                    v.status = 2 ---已领取
                    --break
                end
            end
            -- 没有可以领取的道具 --是否提示
            if isSet(responseData, "rewards") then
                if #responseData.rewards > 0 then
                    GoodsUtils.DrawRewards(responseData.rewards, true)
                    CfUtils.DialogOpen(Constants.UITypeIds.UICommonRewardPop, { rewards = responseData.rewards })
                else
                    GameUtils.Toast(localize("沒有可领取的物品"))
                end
            end
            xTry(function()
                if checkNumber(data.type) == 2 then
                    --大奖领取后
                    xTry(function()
                        ---刷新在线奖励
                        if playerComponent then
                            GameUtils.Request(Interfaces.OverseaOnlineTask, { }, function(request, response)
                                local errCode = checkNumber(response.errCode)
                                if errCode == 0 then
                                    playerDojo.onlineTaskInfo.unlockStatus = 1
                                    playerDojo.onlineTaskInfo.taskList = checkTable(response.data.taskList)
                                    self.data = playerDojo.onlineTaskInfo.taskList
                                    ---修改为解锁的状态,更新主界面按钮状态
                                    Events.Broadcast("ONLINE_REWARD_BUTTON_EVENT")
                                end
                            end)
                        end
                    end)
                else
                    Events.Broadcast("ONLINE_REWARD_BUTTON_EVENT")
                    local taskList = playerDojo.onlineTaskInfo.taskList
                    self.data = taskList
                end
                self:FreshUI()
            end)
        end
    end)
end

function OnlineRewardPreviewDialog:FreshUI()
    local data
    self.position = {}
    local moveIndex = 0
    for i, v in pairs(self.data) do
        if checkNumber(v.type) == 2 then
            data = v
        else
            table.insert(self.position, i)
        end
        if checkNumber(v.status) == 2 then
            moveIndex = i
        end
    end
    ---next day data
    CfUtils.SetActive(self.OnlineRewardCell.transform.parent, data ~= nil)
    if data then
        ---@type OnlineRewardCell
        local env = CfUtils.GetLuaScr(self.OnlineRewardCell, OnlineRewardCellPath)
        env:FreshUI(data, Bind(self, self.OnCellNodeAction))
        env:SetLineActive(true, false)
    end
    ---刷新列表
    local count = #self.position
    --print('====>>', table.dump(self.position, false, 2))
    if not self.ChestList.IsListViewInit then
        self.ChestList:InitListView(count, Bind(self, self.OnRefreshCellIndex))
    else
        GameUtils.ReloadData(self.ChestList, count)
    end
    if moveIndex > 4 then
        self.ChestList:MovePanelToItemIndex(moveIndex - 4)
    else
        self.ChestList:MovePanelToItemIndex(0)
    end
end
function OnlineRewardPreviewDialog:OnRefreshCellIndex(listView, index)
    if index < 0 or index >= #self.position then
        return
    end

    local cell = listView:NewListViewItem("OnlineRewardCell")
    local position = index + 1
    local originPosition = self.position[position]
    local data = self.data[originPosition]
    if not isNull(cell) then
        ---@type OnlineRewardCell
        local tableCellEnv = CfUtils.GetLuaScr(cell, OnlineRewardCellPath)
        if not isNull(tableCellEnv) then
            tableCellEnv:FreshUI(data, Bind(self, self.OnCellNodeAction))
            tableCellEnv:SetLineActive(position ~= 1, position == #self.position)
        end
    end
    return cell
end

function OnlineRewardPreviewDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        ---@type PlayerComponent
        local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        if playerComponent then
            ---@type PlayerDojo
            local playerDojo = playerComponent.playerDojo
            local taskList = playerDojo.onlineTaskInfo.taskList
            self.data = taskList
            self:FreshUI()
        end
    end))
    return coWait
end

function OnlineRewardPreviewDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return OnlineRewardPreviewDialog